import * as React from "react";
import { cx } from "./cx";

export interface CrumbBarItem {
  label: React.ReactNode;
  href?: string;
}

export interface CrumbBarProps extends React.HTMLAttributes<HTMLElement> {
  trail: CrumbBarItem[];
  /** Pixels of scroll before the bar solidifies and the crumbs fade in. */
  threshold?: number;
}

/**
 * The fixed top bar of the house chrome. Transparent at rest; once the
 * page cover scrolls away it gains the paper background and its bottom
 * hairline, and the breadcrumbs fade in.
 */
export function CrumbBar({ trail, threshold = 110, className, ...props }: CrumbBarProps) {
  const [scrolled, setScrolled] = React.useState(false);

  React.useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > threshold);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, [threshold]);

  return (
    <nav
      className={cx("rs-crumb-bar", scrolled && "rs-crumb-bar-scrolled", className)}
      aria-label="Breadcrumbs"
      {...props}
    >
      <div className="rs-crumb-bar-inner">
        <p className="rs-crumbs">
          {trail.map((crumb, index) => {
            const last = index === trail.length - 1;
            return (
              <React.Fragment key={index}>
                {index > 0 && (
                  <span className="rs-crumbs-sep" aria-hidden="true">
                    /
                  </span>
                )}
                {last ? (
                  <span className="rs-crumbs-here">{crumb.label}</span>
                ) : crumb.href ? (
                  <a href={crumb.href}>{crumb.label}</a>
                ) : (
                  <span>{crumb.label}</span>
                )}
              </React.Fragment>
            );
          })}
        </p>
      </div>
    </nav>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Crumb bar — fixed top bar in the house chrome ──
   Transparent at rest; once the page cover scrolls away it gains the
   paper background and its bottom hairline, and the breadcrumbs fade
   in. The inner row starts one module in at the 1024px rail. */
.rs-crumb-bar{position:fixed;top:0;left:0;right:0;z-index:160;display:flex;align-items:center;height:72px;font-size:13px;font-weight:500;letter-spacing:-.01em;line-height:1.3;background:none;border-bottom:1px solid transparent;transition:var(--transition),background-color .2s ease,border-color .2s ease}
.rs-crumb-bar-scrolled{background:var(--bg);border-bottom-color:var(--divider-subtle)}
.rs-crumb-bar-inner{display:flex;align-items:center;gap:20px;width:100%;min-width:0;padding-left:var(--pad)}
.rs-crumb-bar .rs-crumbs{margin:0;opacity:0;transform:translateY(4px);pointer-events:none;transition:opacity .25s ease,transform .25s ease}
.rs-crumb-bar-scrolled .rs-crumbs{opacity:1;transform:none;pointer-events:auto}
.rs-crumb-bar a{color:inherit;text-decoration:none}
@media(min-width:1024px){.rs-crumb-bar-inner{margin-left:204px}}
@media(max-width:640px){.rs-crumb-bar{height:64px;font-size:12px}}
